const price=n=>n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const footer='<footer><strong>Pedidos devem ser realizados no caixa</strong><span>@zedoacai.nf</span></footer>';
const row=(n,p,badge='')=>`<div class="row"><span>${n}</span><i></i><b>${price(p)}</b>${badge?`<small>${badge}</small>`:''}</div>`;
const page=(label,body,cls='')=>`<section class="sheet ${cls}"><div class="vertical">${label}</div><div class="content">${body}</div>${footer}</section>`;
const heading=s=>`<h2><span>${s}</span></h2>`;
function acai(fruit){return page(fruit?'FRUTADOS':'CARDÁPIO',`<img class="mascot" src="/assets/mascote.webp" alt=""><h1>${fruit?'Açaí com<br>creme de fruta':'Açaí'}</h1>${heading('Escolha o tamanho:')}<div class="sizes">${sizes.map(([v,p])=>row(v+' ml',p,v===400?'Mais vendido':v===700?'Melhor custo-benefício':'')).join('')}</div>${heading('Escolha seu açaí:')}<ul class="flavors"><li>Natural</li><li>Sem xarope</li><li>Batido com banana</li><li>Batido com morango</li><li>Batido com maracujá</li></ul>${fruit?heading('Qual creme de fruta?')+'<p class="fruit-options">Cupuaçu · Maracujá · Manga · Sem creme</p>':''}${heading('Até 3 complementos grátis:')}<ul class="free">${free.map(n=>`<li>${n}</li>`).join('')}</ul>${heading('Complementos pagos:')}<div class="extras">${extras.map(([n,p])=>row(n,p)).join('')}</div>`,fruit?'fruit':'acai')}
const specials=page('ESPECIAIS',`<h1 class="banner">Especiais do Zé <small>500 ml</small></h1><div class="specials">${groups.Especiais.map(i=>`<article><img src="/assets/${i.image}" alt="${i.name}"><div><h3>${i.name}</h3><p>${i.desc}</p><b class="price">${price(i.price)}</b></div></article>`).join('')}</div>`,'special-page');
const desserts=page('SOBREMESAS',`<h1 class="banner">Sobremesas</h1><div class="desserts">${groups.Sobremesas.map(i=>`<article>${row(i.name,i.price)}<p>${i.desc}</p></article>`).join('')}</div><h1 class="banner second">Cafeteria</h1><div class="coffee">${groups.Cafeteria.map(i=>`<article>${row(i.name,i.price)}${i.desc?`<p>${i.desc}</p>`:''}</article>`).join('')}</div><img class="bottom-mascot" src="/assets/mascote.webp" alt="">`,'dessert-page');
const snacks=page('CAFETERIA',`<h1 class="banner">Lanches</h1>${groups.Lanches.slice(0,2).map(i=>row(i.name,i.price)).join('')}<p class="note">Consulte opções disponíveis.</p>${heading('Pães de queijo')} ${groups.Lanches.slice(2).map(i=>`<article>${row(i.name,i.price)}${i.desc?`<p class="note">${i.desc}</p>`:''}</article>`).join('')}<h1 class="banner second">Bebidas</h1>${groups.Bebidas.map(i=>row(i.name,i.price)).join('')}<p class="note">Consulte opções disponíveis.</p><div class="self"><strong>Self-service · 6,49 a cada 100 g</strong><p>Inclui sorvetes, açaí, complementos, caldas e cremes.</p></div><img class="snack-logo" src="/assets/logo.webp" alt="Zé do Açaí">`,'snack-page');
document.getElementById('pages').innerHTML=acai(false)+acai(true)+specials+desserts+snacks;
document.getElementById('print').addEventListener('click',async()=>{await document.fonts.ready;await Promise.all([...document.images].map(i=>i.decode().catch(()=>{})));window.print()});
